<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRouter} from 'vue-router'
import pearSample from '@/assets/postharvest/pear-leaf-example.jpg'
import {getToken} from '@/api/auth'
import {visionGet,visionUpload,type VisionRecord} from '@/api/vision'
import PearCameraInput from './PearCameraInput.vue'
const props=defineProps<{farmId:string;selectedId:string|null;plots:{entityId:string;crop:string}[];names:Record<string,string>;embedded?:boolean}>()
const emit=defineEmits<{(e:'ask',question:string):void;(e:'close'):void}>()
const router=useRouter(),plot=ref(props.selectedId||props.plots[0]?.entityId||''),task=ref('leaf'),input=ref<HTMLInputElement>(),mode=ref('upload'),busy=ref(false),error=ref(''),result=ref<any>(),preview=ref(''),graph=ref<any>(),graphError=ref('')
let generation=0,controller:AbortController|undefined
const crop=computed(()=>{const c=props.plots.find(p=>p.entityId===plot.value)?.crop||'';return c.includes('梨')?'pear':c.includes('枣')?'jujube':c.includes('麦')?'wheat':c.includes('番茄')?'tomato':'vegetable'})
const cropName=computed(()=>props.plots.find(p=>p.entityId===plot.value)?.crop||'未选择作物')
const taskOptions=computed(()=>crop.value==='tomato'?[{id:'leaf',label:'番茄叶片症状'},{id:'fruit_ripeness',label:'番茄成熟度'}]:crop.value==='wheat'?[{id:'leaf',label:'叶片症状'},{id:'canopy',label:'冠层水分表型'},{id:'head',label:'麦穗检测'}]:crop.value==='jujube'?[{id:'leaf',label:'叶片症状'},{id:'fruit_bruise',label:'果实损伤'},{id:'fruit_freshness',label:'果实新鲜度'}]:[{id:'leaf',label:'叶片症状'}])
const weight=computed(()=>crop.value==='tomato'?(task.value==='leaf'?'tomato_leaf_yolo11n_cls_v1':'tomato_ripeness_yolo11n_cls_v1'):crop.value==='pear'?'pear_symptom_yolo11n_cls_v1':crop.value==='wheat'?({leaf:'wheat_leaf_yolo11n_cls_v1',canopy:'wheat_water_stress_yolo11n_cls_v1',head:'wheat_head_yolo11n_v1'} as Record<string,string>)[task.value]:crop.value==='jujube'?'jujube_'+task.value+'_yolo11n_cls_v1':'尚无已上线权重')
const observation=computed(()=>{const r=result.value;if(!r)return null;if(crop.value==='pear')return {code:r.vision.symptom,label:r.vision.symptom_cn,score:r.vision.confidence};if(crop.value==='tomato')return {code:r.class,label:({healthy:'健康',bacterial_spot:'细菌性斑点',leaf_miner:'潜叶虫',powdery_mildew:'白粉症状',whitefly:'粉虱',green:'青熟',breakers:'破色',turning:'转色',pink:'粉红',light_red:'浅红',red:'红熟'} as Record<string,string>)[r.class]||r.class,score:r.confidence};if(crop.value==='jujube')return {code:r.prediction.class,label:r.prediction.label_zh,score:r.prediction.confidence};const v=r.visual_observations?.[task.value];return v?{code:v.class,label:v.label_zh||'麦穗检测',score:v.score??v.visual_score??v.mean_confidence,count:v.wheat_head_count}:null})
const pearDetections=computed(()=>crop.value==='pear'?(result.value?.detections||[]):[])
const previewStyle=computed(()=>{const width=result.value?.imageWidth,height=result.value?.imageHeight,ratio=width&&height?width/height:4/3;return{aspectRatio:String(ratio),maxWidth:`${320*ratio}px`}})
const terms:Record<string,string[]>={curl:['卷叶'],spot:['叶斑','斑点','黑星'],slug:['虫害','虫咬','害虫'],insect_damage:['虫害','虫咬'],anthracnose:['炭疽'],powdery_mildew:['白粉'],yellow_leaf:['黄化','黄叶'],leaf_spot_blight:['叶斑','叶枯'],rust:['锈病'],nitrogen_deficiency:['缺氮','氮素'],water_stress:['水分胁迫','缺水','干旱'],fruit_bruise:['损伤','碰伤'],bruise:['损伤','碰伤'],healthy:['健康'],normal:['正常'],fresh:['新鲜','保鲜'],wheat_head:['麦穗','穗数']}
const matches=computed(()=>{if(!observation.value)return [];const keys=terms[observation.value.code]||[observation.value.label];return (graph.value?.nodes||[]).filter((n:any)=>{const text=[n.name,...(Array.isArray(n.aliases)?n.aliases:[])].join(' ');return keys.some(k=>k&&text.includes(k))}).slice(0,8)})
const question=computed(()=>observation.value?`${cropName.value}在${props.names[plot.value]}的${taskOptions.value.find(t=>t.id===task.value)?.label}识别出现“${observation.value.label}”视觉候选。知识图谱中有哪些相关症状、鉴别问题、环境条件和管理资料？应补充哪些观测？不要将视觉候选作为确诊。`:'')
async function request(path:string,body?:FormData){const r=await fetch('/api/multicrop/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+getToken()},body,signal:controller?.signal});const data=await r.json();if(!r.ok)throw Error(data.message||data.error||data.detail||'识别服务不可用');return data}
function clear(){generation++;controller?.abort();controller=undefined;busy.value=false;result.value=undefined;graph.value=undefined;error.value='';graphError.value='';if(preview.value)URL.revokeObjectURL(preview.value);preview.value=''}
watch(()=>[plot.value,task.value],clear);watch(crop,()=>{task.value='leaf'});watch(()=>props.selectedId,id=>{if(id)plot.value=id})
async function infer(file:File){if(busy.value||crop.value==='vegetable')return;if(file.size>8*1024*1024){error.value='图片不能超过 8 MB';return}clear();const current=generation;controller=new AbortController();busy.value=true;preview.value=URL.createObjectURL(file);const c=crop.value,t=task.value;try{let data:any;if(c==='pear'){const created=await visionUpload(props.farmId,plot.value,file);let row:VisionRecord=created;const deadline=Date.now()+125_000;while(['QUEUED','RUNNING'].includes(row.status)&&Date.now()<deadline){await new Promise(resolve=>setTimeout(resolve,500));if(current!==generation)return;row=await visionGet(created.id)}if(['QUEUED','RUNNING'].includes(row.status))throw Error('梨叶识别超时，请稍后查看视觉记录');if(row.status==='FAILED')throw Error(row.error||'梨叶识别失败');const detections=row.result?.detections||[],first=detections[0];data={vision:{symptom:first?.className||'unknown',symptom_cn:first?.label||'未检出可靠候选',confidence:first?.confidence||0},detections,imageWidth:row.result?.imageWidth,imageHeight:row.result?.imageHeight}}else{const body=new FormData();let path='';if(c==='tomato'){path='tomato/vision/analyze';body.append('image',file);body.append('task',t)}if(c==='jujube'){path='jujube/vision/analyze';body.append('image',file);body.append('task',t)}if(c==='wheat'){path='wheat/diagnose';body.append(t+'_image',file);body.append('knowledge_enabled','false')}data=await request(path,body)}if(current!==generation)return;result.value=data;try{const g=await request('graph?crop='+(c==='tomato'?'vegetable':c));if(current===generation)graph.value=g}catch(e){if(current===generation)graphError.value='图谱关联加载失败，可稍后重新进入图谱检索。'}}catch(e){if(current===generation)error.value=(e as Error).message}finally{if(current===generation)busy.value=false}}
async function sample(){if(busy.value)return;try{const r=await fetch(pearSample);if(!r.ok)throw Error('示范图片读取失败');await infer(new File([await r.blob()],'公开鸭梨叶片示范.jpg',{type:'image/jpeg'}))}catch(e){error.value=(e as Error).message}}
function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)infer(f);(e.target as HTMLInputElement).value=''}
function openGraph(id?:string){router.push({path:'/multicrop',query:{mode:'knowledge',crop:crop.value==='tomato'?'vegetable':crop.value,entity:id,question:question.value}})}
onBeforeUnmount(clear)
</script>
<template><section class="crop-vision"><label>识别地块<select v-model="plot" aria-label="识别地块"><option v-for="p in plots" :key="p.entityId" :value="p.entityId">{{names[p.entityId]||p.entityId}} · {{p.crop}}</option></select></label><div class="model-binding"><strong>{{cropName}} · 自动匹配权重</strong><code>{{weight}}</code><small>模型按地块作物选择，识别分数不等于疾病概率。</small></div><template v-if="crop!=='vegetable'"><label>识别对象<select v-model="task" aria-label="识别对象"><option v-for="t in taskOptions" :key="t.id" :value="t.id">{{t.label}}</option></select></label><div class="input-tabs"><button :aria-pressed="mode==='upload'" @click="mode='upload'">图片上传</button><button :aria-pressed="mode==='camera'" @click="mode='camera'">摄像头</button></div><button v-if="mode==='upload'" class="primary" :disabled="busy" @click="input?.click()">{{busy?'识别与关联中…':'上传图片并识别'}}</button><div v-if="crop==='pear'&&mode==='upload'" class="sample-card"><img :src="pearSample" alt="鸭梨叶片识别示范图片"/><div><strong>鸭梨叶片示范</strong><small>公开数据集样本 · CC BY 4.0</small><button :disabled="busy" @click="sample">试用示范图片 ↗</button><a href="https://huggingface.co/datasets/salahkhenfer/pear-pests-dataset" target="_blank" rel="noopener">查看来源</a></div></div><input ref="input" type="file" hidden accept="image/jpeg,image/png,image/webp" @change="upload"/><PearCameraInput v-if="mode==='camera'" :key="plot+task" :enabled="!busy" :infer="infer"/><div v-if="preview" class="preview-stage" :style="previewStyle" aria-label="识别图像与检测框"><img :src="preview" class="vision-preview" alt="当前识别图像"/><svg v-if="pearDetections.length" class="detection-overlay" :viewBox="`0 0 ${result.imageWidth} ${result.imageHeight}`" preserveAspectRatio="none" aria-label="梨叶检测框"><g v-for="(d,i) in pearDetections" :key="i"><rect :x="d.box[0]" :y="d.box[1]" :width="d.box[2]-d.box[0]" :height="d.box[3]-d.box[1]" fill="none" stroke="#b6fa78" :stroke-width="Math.max(2,result.imageWidth/300)"/><text :x="d.box[0]+4" :y="Math.max(18,d.box[1]-6)" fill="#e6ffcc" stroke="#1c3925" stroke-width=".7" paint-order="stroke" :font-size="Math.max(14,result.imageWidth/38)">{{d.label}} {{(d.confidence*100).toFixed(1)}}%</text></g></svg></div></template><p v-else class="notice">当前地块暂无专用视觉权重。番茄地块支持叶片症状和果实成熟度识别；其他设施作物可进入知识图谱查询，不能套用其他作物模型。</p><p v-if="error" role="alert" class="error">{{error}}</p><article v-if="observation" class="vision-result"><small>模型视觉候选 · {{props.names[plot]}}</small><h3>{{observation.label}}</h3><p>识别分数 {{((observation.score||0)*100).toFixed(1)}}% <span v-if="observation.count!=null">· {{observation.count}} 个麦穗</span></p><h4>关联知识图谱</h4><p v-if="graphError">{{graphError}}</p><button v-for="node in matches" :key="node.id" class="graph-link" @click="openGraph(node.id)">{{node.name}} <span>查看关联问题 ↗</span></button><p v-if="graph&&!matches.length" class="notice">当前图谱没有匹配到该候选的实体，请检索相关资料并补充鉴别信息。</p><div class="knowledge-question"><strong>对应知识问题</strong><p>{{question}}</p></div><button class="primary" @click="openGraph(matches[0]?.id)">在知识图谱中查询 ↗</button><button class="secondary" @click="emit('ask',question)">交给 Agent 检索与核验</button></article><button v-else-if="crop==='vegetable'" class="primary" @click="openGraph()">进入设施蔬菜知识图谱 ↗</button></section></template>
<style scoped>.crop-vision{font-family:var(--font-sans);color:var(--ui-ink)}label{display:block;font-size:11px;color:#7b9383;margin:12px 0}select{display:block;width:100%;border:1px solid var(--ui-brand-soft);border-radius:9px;background:white;padding:11px;color:var(--ui-ink);font:inherit;margin-top:7px}.model-binding{padding:14px;background:var(--ui-brand-soft);border-radius:10px;display:flex;flex-direction:column;gap:7px}.model-binding strong{font-size:12px;color:var(--ui-brand)}code{font-size:10px;overflow-wrap:anywhere}.model-binding small{font-size:9px;color:#8ba194}.input-tabs{display:flex;gap:8px;margin:15px 0}.input-tabs button,.secondary{border:1px solid var(--ui-brand-soft);border-radius:8px;background:white;padding:9px 13px;font:inherit;font-size:11px;color:var(--ui-brand);cursor:pointer}.input-tabs button[aria-pressed=true]{background:var(--ui-brand-soft)}.primary{width:100%;border:0;border-radius:9px;padding:12px;background:var(--ui-brand);color:white;font:inherit;font-size:11px;cursor:pointer;margin:12px 0}.primary:disabled{opacity:.5;cursor:wait}.preview-stage{position:relative;width:100%;max-height:320px;margin:15px 0;background:#edf3ee;border-radius:11px;overflow:hidden}.vision-preview{display:block;width:100%;height:100%;max-height:320px;object-fit:contain;border-radius:11px}.detection-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.vision-result{padding:16px;border:1px solid var(--ui-brand-soft);border-radius:12px;background:#f7faf8}.vision-result small{font-size:10px;color:#8ba194}.vision-result h3{font-size:19px;margin:10px 0;color:var(--ui-brand)}.vision-result p{font-size:11px;line-height:1.9;color:#82998a}.vision-result h4{font-size:12px;margin:21px 0 10px}.graph-link{display:flex;align-items:center;justify-content:space-between;gap:10px;border:1px solid var(--ui-brand-soft);border-radius:8px;background:white;color:var(--ui-brand);padding:11px;width:100%;font:inherit;font-size:11px;margin:7px 0;cursor:pointer}.graph-link span{font-size:9px;color:#9aafa1}.knowledge-question{background:#edf4ef;border-radius:9px;padding:12px;margin-top:14px}.knowledge-question strong{font-size:11px;color:#739780}.knowledge-question p{margin-bottom:0}.notice{padding:12px;background:#f3f5ed;color:#8a9272;font-size:11px;line-height:1.9;border-radius:9px}.error{background:#fff0e8;padding:12px;border-radius:9px;color:#a57550;font-size:11px}.secondary{width:100%}button:focus-visible,select:focus-visible{outline:2px solid var(--ui-brand);outline-offset:3px}</style>
<style scoped>.sample-card{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid var(--ui-brand-soft);border-radius:11px;background:#f5f9f6;margin:12px 0}.sample-card img{width:78px;height:78px;object-fit:contain;background:white;border-radius:8px}.sample-card>div{display:flex;flex-direction:column;gap:6px}.sample-card strong{font-size:11px;color:var(--ui-brand)}.sample-card small,.sample-card a{font-size:9px;color:#8ba194}.sample-card button{border:0;border-radius:6px;padding:7px 10px;background:var(--ui-brand-soft);color:var(--ui-brand);font:inherit;font-size:10px;cursor:pointer}.sample-card button:disabled{opacity:.5}</style>
